#!/bin/bash
# Auto-generated by skill-to-sandbox Phase 9.4.
# Idempotent repair for ansible-2.0.0 sandbox environment.
# Run this *inside the agent container* before the usability run if
# check_environment.sh reports failures. The hooks under
# mock_assets/skill_hooks/ should ideally do all this, but we keep
# fix_environment.sh as a fallback for environments where those
# hooks only land in /etc/profile.d/.
set -u

echo "[fix-1] promoting env vars from /etc/profile.d/ to /etc/environment"
val=""
for f in /etc/profile.d/*.sh; do
    [ -f "$f" ] || continue
    found=$(grep -E "^\s*export\s+ANSIBLE_HOST_KEY_CHECKING=" "$f" | tail -1 | sed -E "s/^\s*export\s+ANSIBLE_HOST_KEY_CHECKING=//; s/^\"//; s/\"$//; s/^\x27//; s/\x27$//")
    if [ -n "$found" ]; then val="$found"; fi
done
if [ -n "$val" ] && ! grep -q "^ANSIBLE_HOST_KEY_CHECKING=" /etc/environment 2>/dev/null; then
    echo "ANSIBLE_HOST_KEY_CHECKING=$val" >> /etc/environment
    echo "  -> ANSIBLE_HOST_KEY_CHECKING promoted to /etc/environment"
fi

echo "[fix] done. Re-run check_environment.sh to verify."
